'use strict';
let mapData=null,mapTicker='BE',mapSelection=null,mapPage=0,mapRequest=0,mapThesis='';
const mapKinds={cluster:'Buying overlap',political:'Political trade',insider:'Corporate insider',award:'Contract / grant',policy:'Policy',bill:'Bill',earnings:'Catalyst',agent:'Research lead',thesis:'Why now',company:'Company',market:'Market',contract:'Contract'};
const mapStatus={record:'Source record',sourced:'Sourced claim',candidate:'Unverified link',inference:'Hypothesis'};
async function openResearchMap(symbol=marketSymbol||'BE',thesis=''){mapTicker=tickerValid(symbol)?symbol:'BE';mapThesis=thesis;mapPage=0;changeView('map');$('#mapTicker').value=mapTicker;await loadResearchMap()}
async function loadResearchMap(){const request=++mapRequest;$('#mapStatus').textContent='Loading connections…';try{const r=await getLiveJSON('/api/research/map?symbol='+mapTicker);if(request!==mapRequest)return;if(r.error)throw Error();mapData=r;mapSelection=mapThesis?'thesis:'+mapThesis:null;$('#mapThesis').innerHTML='<option value="">All connections</option>'+r.nodes.filter(n=>n.kind==='thesis').map(n=>`<option value="${esc(n.articleId)}">${esc(n.label)}</option>`).join('');$('#mapThesis').value=mapThesis;renderMap();renderMapDetail();}catch{if(request===mapRequest)$('#mapStatus').textContent='Map unavailable. Retry to load saved evidence.'}}
function visibleMapNodes(){if(!mapData)return [];let nodes=mapData.nodes.filter(n=>n.kind!=='stock');if(mapThesis){const id='thesis:'+mapThesis,ids=new Set(mapData.edges.filter(e=>e.to===id).map(e=>e.from));ids.add(id);nodes=nodes.filter(n=>ids.has(n.id))}const type=$('#mapType').value,query=$('#mapSearch').value.toLowerCase();nodes.sort((a,b)=>({thesis:0,cluster:1,political:2,market:3}[a.kind]??4)-({thesis:0,cluster:1,political:2,market:3}[b.kind]??4)||(b.date||'').localeCompare(a.date||''));return nodes.filter(n=>(!type||n.status===type||type==='focus'&&n.status!=='candidate')&&(n.label+' '+n.detail+' '+(mapKinds[n.kind]||n.kind)).toLowerCase().includes(query))}
function mapLineText(text,max=23){const words=String(text||'').split(/\s+/),lines=[];let line='';for(const w of words){if((line+' '+w).trim().length>max&&line){lines.push(line);line=w}else line=(line+' '+w).trim()}if(line)lines.push(line);return lines.slice(0,2).map((x,i)=>esc(x+(i===1&&lines.length>2?'…':'')))}
function renderMap(){if(!mapData)return;const all=visibleMapNodes(),mobile=$('#mapCanvas').clientWidth<600,size=mobile?6:10,total=Math.max(1,Math.ceil(all.length/size));mapPage=Math.min(mapPage,total-1);const nodes=all.slice(mapPage*size,(mapPage+1)*size),W=mobile?380:860,H=mobile?490:490,cx=W/2,cy=H/2;
 const positions=new Map([['stock:'+mapTicker,{x:cx,y:cy}]]);nodes.forEach((n,i)=>{const angle=-Math.PI/2+2*Math.PI*i/Math.max(1,nodes.length);positions.set(n.id,{x:cx+Math.cos(angle)*(mobile?120:300),y:cy+Math.sin(angle)*177})});
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="${esc(mapTicker)} research connection map">`;
 for(const n of nodes){const p=positions.get(n.id),edge=mapData.edges.find(e=>e.from===n.id&&(mapThesis?e.to==='thesis:'+mapThesis:true))||mapData.edges.find(e=>e.from===n.id);const dest=positions.get(edge?.to);if(!dest)continue;svg+=`<line x1="${p.x}" y1="${p.y}" x2="${dest.x}" y2="${dest.y}" class="map-edge ${n.status}"/>`}
 svg+=`<circle cx="${cx}" cy="${cy}" r="39" class="map-hub"/><text x="${cx}" y="${cy-2}" text-anchor="middle" class="map-hub-label">${esc(mapTicker)}</text><text x="${cx}" y="${cy+16}" text-anchor="middle" class="map-hub-sub">${all.length} connections</text>`;
 nodes.forEach((n,i)=>{const p=positions.get(n.id),label=n.subtitle?[esc(n.label),esc(n.subtitle)]:mapLineText(n.label,mobile?17:25),w=mobile?116:178;svg+=`<g class="map-node ${n.status} ${mapSelection===n.id?'selected':''}" role="button" tabindex="0" data-map-node="${esc(n.id)}" aria-label="${esc((mapKinds[n.kind]||n.kind)+': '+n.label+'; '+mapStatus[n.status])}"><rect x="${p.x-w/2}" y="${p.y-37}" width="${w}" height="82" rx="8"/><text x="${p.x}" y="${p.y-20}" text-anchor="middle" class="map-node-kind">${i+1+mapPage*size} · ${esc(mapKinds[n.kind]||n.kind)}</text>${label.map((s,j)=>`<text x="${p.x}" y="${p.y+j*14-2}" text-anchor="middle" class="map-node-label">${s}</text>`).join('')}<text x="${p.x}" y="${p.y+32}" text-anchor="middle" class="map-node-date">${esc(n.kind==='political'?'Trade '+(n.eventDate||'').slice(5)+' / pub '+(n.date||'').slice(5):n.date||'Date unknown')}</text></g>`});
 $('#mapCanvas').innerHTML=svg+'</svg>';$('#mapStatus').textContent=all.length+' connections · page '+(mapPage+1)+' / '+total+' · tap a node';$('#mapPrev').disabled=mapPage===0;$('#mapNext').disabled=mapPage===total-1;
 $('#mapList').innerHTML=all.map((n,i)=>`<button data-map-node="${esc(n.id)}" class="map-list-row"><b>${i+1}. ${esc(n.label)}</b><span>${esc(mapKinds[n.kind]||n.kind)} · ${esc(mapStatus[n.status])} · ${esc(n.date||'Date unknown')}</span></button>`).join('')||'<p class="muted">No matching connections in the loaded sources.</p>';
 $('#mapCoverage').innerHTML=(mapData.coverage||[]).map(c=>`<p><b>${esc(c.source)}</b> · ${c.count} records · ${esc(c.state)}${c.checkedAt?' · checked '+esc(stamp(c.checkedAt)):''}</p>`).join('');
}
function renderMapDetail(){const n=mapData?.nodes.find(n=>n.id===mapSelection),el=$('#mapDetail');if(!n){const theses=mapData?.nodes.filter(n=>n.kind==='thesis')||[];el.innerHTML=`<h2>Why ${esc(mapTicker)} now?</h2>${theses.length?theses.slice(0,4).map(a=>`<button class="map-thesis" data-map-node="${esc(a.id)}"><b>${esc(a.label)}</b><span>${esc(a.detail)}</span></button>`).join(''):'<p>No supported thesis published yet. Select a record to inspect its dates and source. An apparent connection still needs a causal explanation and a catalyst.</p>'}<button class="secondary" data-ticker="${esc(mapTicker)}">Open price chart ↗</button>`;return}
 const relations=mapData.edges.filter(e=>e.from===n.id||e.to===n.id);el.innerHTML=`<small class="map-detail-status">${esc(mapKinds[n.kind]||n.kind)} · ${esc(mapStatus[n.status])}</small><h2>${esc(n.label)}</h2><p>${esc(n.detail)}</p><p class="muted">${n.date?'Source date '+date(n.date):'Source date unknown'}${n.eventDate?' · Event '+date(n.eventDate):''}<br>First observed ${n.firstObserved?esc(stamp(n.firstObserved)):'Not recorded'}</p>${n.provenance?'<p>'+esc(n.provenance)+'</p>':''}${n.url?researchLink(n.url,'Open original source ↗'):''}${n.kind!=='thesis'&&n.sources?n.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · '):''}${n.kind==='thesis'?`<dl class="map-thesis-fields"><dt>Why now</dt><dd>${esc(n.why)}</dd><dt>Already priced in?</dt><dd>${esc(n.pricedIn)}</dd><dt>Next confirmation</dt><dd>${esc(n.watch)}</dd><dt>Invalidation</dt><dd>${esc(n.invalidation)}</dd><dt>Counterargument</dt><dd>${esc(n.risk)}</dd><dt>Horizon</dt><dd>${esc(n.horizon)}</dd></dl>${n.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}${n.review?'<p><b>Latest review: '+esc(n.review.verdict)+'</b> '+esc(n.review.summary)+'</p>':''}<div id="mapThesisPerformance">Loading performance…</div>`:''}<h3>Connections</h3>${relations.map(e=>{const target=mapData.nodes.find(t=>t.id===(e.from===n.id?e.to:e.from));return target?`<button class="map-relation" data-map-node="${esc(target.id)}">${esc(e.relation)} → ${esc(target.label)}</button>`:''}).join('')}`;
 if(n.kind==='thesis'){const selected=n.id;getLiveJSON('/api/research/performance?id='+n.articleId).then(p=>{articleMetrics.set(n.articleId,p);if(mapSelection===selected&&$('#mapThesisPerformance'))$('#mapThesisPerformance').innerHTML=articlePerformanceHTML({id:n.articleId,tickers:[mapTicker]})}).catch(()=>{if(mapSelection===selected&&$('#mapThesisPerformance'))$('#mapThesisPerformance').textContent='Performance unavailable'})}
}
function selectMapNode(id){mapSelection=id;renderMap();renderMapDetail();if(innerWidth<800)$('#mapDetail').scrollIntoView({block:'nearest',behavior:'smooth'})}
if(typeof window!=='undefined'){
 $('#mapForm').onsubmit=e=>{e.preventDefault();openResearchMap($('#mapTicker').value.trim().toUpperCase())};$('#mapRefresh').onclick=loadResearchMap;
 for(const id of ['mapType','mapSearch'])$('#'+id).addEventListener(id==='mapSearch'?'input':'change',()=>{mapPage=0;renderMap()});$('#mapThesis').onchange=e=>{mapThesis=e.target.value;mapSelection=mapThesis?'thesis:'+mapThesis:null;mapPage=0;renderMap();renderMapDetail()};
 $('#mapPrev').onclick=()=>{mapPage--;renderMap()};$('#mapNext').onclick=()=>{mapPage++;renderMap()};
 document.addEventListener('click',e=>{const open=e.target.closest('[data-map]');if(open)openResearchMap(open.dataset.map||marketSymbol,open.dataset.thesis||'');const n=e.target.closest('[data-map-node]');if(n)selectMapNode(n.dataset.mapNode)});
 $('#mapCanvas').addEventListener('keydown',e=>{const n=e.target.closest('[data-map-node]');if(n&&['Enter',' '].includes(e.key)){e.preventDefault();selectMapNode(n.dataset.mapNode)}});
 let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if(view==='map')renderMap()},150)});
 setInterval(()=>{if(!document.hidden&&view==='map')loadResearchMap()},15*60000);
}
